def _parse_ruby_link(inline: 'InlineParser', state: 'InlineState', pos: int,
    tokens: List[Dict[str, Any]]) ->Optional[int]:
    """Parse link after ruby text, e.g., [ruby(text)][ref] or [ruby(text)](/url)"""
    if pos >= len(state.src):
        return None

    if state.src[pos] == '[':
        # Reference link [label]
        label_match = parse_link_label(state.src, pos)
        if label_match:
            label_pos = label_match[0]
            label = label_match[1]

            for tok in tokens:
